static int Wurzel(int x)
{
    if (x < 0)
        throw new ArgumentException("negativ");
    return (int)Math.Sqrt(x);
}

int summe = 0;
int[] werte = { 16, -4, 9 };
try
{
    foreach (int w in werte)
        summe += Wurzel(w);
}
catch (ArgumentException ex)
{
    Console.Write(ex.Message + " ");
}
Console.WriteLine(summe);

