try
{
    throw new ZugException("Feld 3");
}
catch (SpielException ex)
{
    Console.WriteLine("Spiel: " + ex.Message);
}
catch (ZugException ex)
{
    Console.WriteLine("Zug: " + ex.Message);
}

class SpielException : Exception
{
    public SpielException(string m) : base(m) { }
}

class ZugException : SpielException
{
    public ZugException(string m) : base("Zug ungültig: " + m) { }
}

